def parse_pairs(s):
    pairs = {}
    while s:
        s = s.strip()
        if '=' not in s or s[0] == '=' or s[-1] == '=':
            s = s[1:] if s and s[0] == ';' else s[:-1] if s and s[-1] == ';' else ''
            continue
        key, rest = s.split('=', 1)
        key = key.strip()
        if rest[0] == "'":
            value, rest = rest[1:].partition("'")[2], rest[2:]
            value = value.replace("';", ";").replace("',", ",")
        else:
            value, rest = rest.split(';', 1) if ';' in rest else rest.split('=', 1)[1:]
            value = value.strip()
        pairs[key] = value
        s = rest
    return pairs
